UPDATE lessons SET title='Year 3, Week 21, Lesson 1: Day and night', data=json_patch(data,'{"child_mission":"Day and night happen because Earth spins (rotates). The side facing the Sun has day; the side facing away has night.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same science idea to a new object or material, then compare two pieces of evidence for strength.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nIf it is day where you are, what is likely on the opposite side of Earth?\n\nFEEDBACK\nNight (approximately opposite).\n\nWATCH FOR\nThinking the Sun moves around Earth each day is a common alternative idea; the Year 3 model uses Earth’s spin.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nBuild a ball-and-torch day/night model. Draw day and night on a circle diagram. Write two sentences using spin/rotate language.\n\nWrite a short reflection naming one observation or step you corrected and why.","interactive_activities":null,"learning_area":"Science and Technology","learning_intention":"Day and night happen because Earth spins (rotates). The side facing the Sun has day; the side facing away has night.","lesson_number":1,"lesson_role":"Investigate","materials":["Paper or typed answer space","Pencil","Optional: safe everyday objects for observation"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["ST2-SCI-01"],"parent_notes":"Parent: Marking guidance for the independent task: Build a ball-and-torch day/night model. Draw day and night on a circle diagram. Write two sentences using spin/rotate language. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Original response on new material: Night (approximately opposite). Reasoning: I used day by attending to night and explain why it matters rather than copying the worked model.\n\nParent: Written model 2: Common error: Thinking the Sun moves around Earth each day is a common alternative idea; the Year 3 model uses Earth’s spin. Correction: Night (approximately opposite). Why: the correction restores accurate use of day.\n\nParent: Likely misconception: Thinking the Sun moves around Earth each day is a common alternative idea; the Year 3 model uses Earth’s spin. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Investigate or describe a fresh example (not the worked objects) that uses day. Record evidence and explain how it supports your claim.\n\nParent: Short-answer focus 2: Name one science misconception about day, correct it with evidence, and say why the correction works.\n\nParent: Marking notes: Require a new example, named observations and a claim–evidence link. / Require misconception + corrected claim + evidence reason..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":2,"explanation":"Night (approximately opposite). This matches the lesson skill for day.","options":["Ignore the task and invent an unrelated answer.","Copy the worked example and call it independent work.","Night (approximately opposite).","Thinking the Sun moves around Earth each day is a common alternative idea; the Year 3 model uses Earth’s spin."],"question":"If it is day where you are, what is likely on the opposite side of Earth?","type":"multiple_choice"},{"correct_index":3,"explanation":"Thinking the Sun moves around Earth each day is a common alternative idea; the Year 3 model uses Earth’s spin. That misconception weakens accuracy; the other choices align with the lesson idea.","options":["Day and night happen because Earth spins (rotates). The side facing the Sun has day; the side facing away has night.","Night (approximately opposite).","Careful use of night and explain why it matters with clear evidence.","Thinking the Sun moves around Earth each day is a common alternative idea; the Year 3 model uses Earth’s spin."],"question":"Which statement is a common mistake when practising day?","type":"multiple_choice"},{"correct_index":0,"explanation":"Understanding is shown by new evidence and named night and explain why it matters, not by copying the model.","options":["Apply the idea with new evidence and name the night and explain why it matters used.","Repeat the worked example wording with no new evidence.","Choose randomly because any option could be right.","Treat a missing detail as a proven fact."],"question":"A learner is practising day. Which approach best shows understanding?","type":"multiple_choice"},{"correct_index":1,"explanation":"Trustworthy science claims rest on observable evidence.","options":["Thinking the Sun moves around Earth each day is a common alternative idea; the Year 3 model uses Earth’s spin.","Use observable features or measurements as evidence, not appearance alone.","Decide from which object looks most exciting.","Copy a label from the lesson title with no observation."],"question":"New examples: a charging phone, a nesting bird, glass marble, fallen dry leaf. Which habit makes a scientific sort or claim trustworthy?","type":"multiple_choice"},{"correct_index":3,"explanation":"Science claims need named observations linked to the claim.","options":["A longer story with no observation.","A label copied from the title with no evidence.","Thinking the Sun moves around Earth each day is a common alternative idea; the Year 3 model uses Earth’s spin.","Named observation plus how it supports the claim."],"question":"Which record best supports a science claim about day?","type":"multiple_choice"},{"correct_index":2,"explanation":"Night (approximately opposite). applies the science idea with evidence.","options":["Ignore the task and invent an unrelated answer.","Copy the worked example and call it independent work.","Night (approximately opposite).","Thinking the Sun moves around Earth each day is a common alternative idea; the Year 3 model uses Earth’s spin."],"question":"Using this idea — Day and night happen because Earth spins (rotates). The side facing the Sun has day; the side… — which choice is strongest?","type":"multiple_choice"},{"correct_index":1,"explanation":"Fair tests change one variable and control the rest.","options":["Ignore measurements and decide by which looks nicer.","Change one variable and keep the other conditions the same.","Change several conditions at once so something happens faster.","Stop early when you like the first result."],"question":"Which investigation habit keeps a comparison fair?","type":"multiple_choice"},{"correct_index":1,"explanation":"Transfer needs a new object or context with evidence.","options":["Copy the worked example and call it independent work.","Test or describe a new object or context and cite fresh evidence.","Repeat the worked example objects unchanged.","Invent a dramatic result with no observation."],"question":"Which next step best shows transfer of day?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Require a new example, named observations and a claim–evidence link.","question":"Investigate or describe a fresh example (not the worked objects) that uses day. Record evidence and explain how it supports your claim.","sample_answer":"Original response on new material: Night (approximately opposite). Reasoning: I used day by attending to night and explain why it matters rather than copying the worked model.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Require misconception + corrected claim + evidence reason.","question":"Name one science misconception about day, correct it with evidence, and say why the correction works.","sample_answer":"Common error: Thinking the Sun moves around Earth each day is a common alternative idea; the Year 3 model uses Earth’s spin. Correction: Night (approximately opposite). Why: the correction restores accurate use of day.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent evidence and reflection, with reasons where requested.","review_status":"unreviewed","seed_key":"s2-sci-y3-w21-l1","sort_activity":null,"source_note":"Proposed Stage 2 NESA Science and Technology alignment using catalogue outcome codes; content-point mapping remains pending.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise day.","Read the mission before you start observing or testing.","Keep the property or variable you are studying in view."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your evidence with the feedback.","Adjust anything that does not match the method."],"learn":["Study how the first demonstration is built.","Point to the observation or step that carries the idea.","Then write the reason without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore observations or fair tests.","Prefer accurate evidence over a guess that merely looks neat."],"submit":["Confirm that your evidence and reason are both present.","Proofread labels, measurements and sequence of steps.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked model.","Name one exact observation or test step before you decide.","Try the small prompt before opening the comparison."],"teach1":["Return to the model and list the key observations.","Say what each observation shows about the idea.","A final label alone is weaker than recorded evidence."],"teach2":["Compare a weak claim with stronger evidence.","Change the claim or method, not only how neat the drawing looks.","Name the mistake you are repairing."],"teach3":["Choose a fresh object or context that still uses the same skill.","Write one reason in your own words.","Do not retype the worked model as your answer."],"write":["Follow every part of the independent instructions.","Include original evidence and a short reason.","Save work that shows the skill on new objects or data."]},"subject":"Earth and Space","success_criteria":["I can use day with a specific example from this lesson.","I can identify night and explain why it matters.","I can practise Earth independently on a new prompt.","I can notice spin needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":3,"explanation":"Day and night happen because Earth spins (rotates). The side facing the Sun has day; the side facing away has night. Supported records follow the actual observations and purpose of the task. Apply the lesson idea with evidence.","options":["A claim unrelated to the observation or test.","An answer copied without understanding.","A guess with no evidence.","Day and night happen because Earth spins (rotates). The side facing the Sun has day; the side facing away has night."],"question":"Which choice best shows accurate use of this idea about day?","type":"multiple_choice"},"example":"WORKED MODEL\nTorch as Sun, ball as Earth: spin the ball — half lit, half dark. People on the lit side see day; on the dark side see night.\n\nTRY FIRST\nIf it is day where you are, what is likely on the opposite side of Earth?\n\nFEEDBACK\nNight (approximately opposite).","explain":"Day and night happen because Earth spins (rotates). The side facing the Sun has day; the side facing away has night.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen or measured.\n\nHOW TO WORK\nRead the worked example and name the observations, properties or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Thinking the Sun moves around Earth each day is a common alternative idea; the Year 3 model uses Earth’s spin. Correct the claim or method, not just the neatness of the diagram.","title":"Understand and model","visual":[{"alt":"Day and night model.","caption":"Sun stays; Earth rotates.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Earth spins</text><text x=\"28\" y=\"78\">lit side day</text><text x=\"358\" y=\"42\">Dark side</text><text x=\"358\" y=\"78\">night</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which observation matters most.","who":"pip"},{"text":"Name the observations, properties or test steps that carry the idea before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this model: Torch as Sun, ball as Earth: spin the ball — half lit, half dark. People on the lit side see day; on the dark side see n Then write your own evidence.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which observation matters most.\nJuno: Name the observations, properties or test steps that carry the idea before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this model: Torch as Sun, ball as Earth: spin the ball — half lit, half dark. People on the lit side see day; on the dark side see n Then write your own evidence."}}]},{"check":{"correct_index":3,"explanation":"Make the science idea visible: name the observation, property or test step you used and say why it supports the claim. Supported records follow the actual observations and purpose of the task. Apply the lesson idea with evidence.","options":["A claim unrelated to the observation or test.","An answer copied without understanding.","A guess with no evidence.","Make the science idea visible: name the observation, property or test step you used and say why it supports the claim."],"question":"Which choice best shows accurate use of this idea about day?","type":"multiple_choice"},"example":"WORKED MODEL\nTorch as Sun, ball as Earth: spin the ball — half lit, half dark. People on the lit side see day; on the dark side see night. Look at each observation, variable or design choice that carries the idea.\n\nTRY FIRST\nList the key observations or steps from the model and say what each one shows.\n\nFEEDBACK\nThe most useful record names the evidence and the reason it supports the claim, not only a label.","explain":"Make the science idea visible: name the observation, property or test step you used and say why it supports the claim.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen or measured.\n\nHOW TO WORK\nRead the worked example and name the observations, properties or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Writing only a final label without evidence does not show scientific thinking. Correct the claim or method, not just the neatness of the diagram.","title":"Show the evidence","visual":[{"alt":"Ball-and-torch demo.","caption":"Opposite side is night.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Torch</text><text x=\"28\" y=\"78\">Sun stand-in</text><text x=\"358\" y=\"42\">Ball</text><text x=\"358\" y=\"78\">Earth stand-in</text></g></svg>"}]},{"check":{"correct_index":1,"explanation":"Use an intentionally incorrect claim as a comparison. Name its specific science error, then show the corrected evidence-based claim. Supported records follow the actual observations and purpose of the task. Apply the lesson idea with evidence.","options":["A guess with no evidence.","Use an intentionally incorrect claim as a comparison. Name its specific science error, then show the corrected evidence-based claim.","A claim unrelated to the observation or test.","An answer copied without understanding."],"question":"Which choice best shows accurate use of this idea about day?","type":"multiple_choice"},"example":"WORKED MODEL\nThinking the Sun moves around Earth each day is a common alternative idea; the Year 3 model uses Earth’s spin. Here is a more productive model: Torch as Sun, ball as Earth: spin the ball — half lit, half dark. People on the lit side see day; on the dark side see night.\n\nTRY FIRST\nDescribe why the warned-against claim fails, then write a corrected claim with evidence.\n\nFEEDBACK\nNight (approximately opposite).","explain":"Use an intentionally incorrect claim as a comparison. Name its specific science error, then show the corrected evidence-based claim.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen or measured.\n\nHOW TO WORK\nRead the worked example and name the observations, properties or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Changing the wording without repairing the evidence does not fix the error. Thinking the Sun moves around Earth each day is a common alternative idea; the Year 3 model uses Earth’s spin. Correct the claim or method, not just the neatness of the diagram.","title":"Test a misconception"},{"check":{"correct_index":2,"explanation":"Use the same science idea on a new object, material or context, not a copy of the worked example. Review accuracy of observations. Supported records follow the actual observations and purpose of the task. Apply the lesson idea with evidence.","options":["An answer copied without understanding.","A guess with no evidence.","Use the same science idea on a new object, material or context, not a copy of the worked example. Review accuracy of observations.","A claim unrelated to the observation or test."],"question":"Which choice best shows accurate use of this idea about day?","type":"multiple_choice"},"example":"WORKED MODEL\nDay and night happen because Earth spins (rotates). The side facing the Sun has day; the side facing away has night. Now choose a different example to show you can transfer the idea.\n\nTRY FIRST\nInvestigate or describe one fresh example that uses the same skill and write a short evidence-based reason.\n\nFEEDBACK\nThe new example should use the same science idea as the model, but contain different objects or data.","explain":"Use the same science idea on a new object, material or context, not a copy of the worked example. Review accuracy of observations.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen or measured.\n\nHOW TO WORK\nRead the worked example and name the observations, properties or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Repeating the worked example cannot show transfer to new evidence. Correct the claim or method, not just the neatness of the diagram.","title":"Transfer to a new investigation"}],"title":"Year 3, Week 21, Lesson 1: Day and night","unit_number":5,"unit_title":"Earth, Sun and Moon","week":21,"week_in_unit":1,"word_challenges":null,"worked_example":"WORK THROUGH THIS\nTorch as Sun, ball as Earth: spin the ball — half lit, half dark. People on the lit side see day; on the dark side see night.\n\nWrite what makes this example accurate, naming the observations, properties or test steps used.","worked_visuals":[{"alt":"Day and night model.","caption":"Sun stays; Earth rotates.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Earth spins</text><text x=\"28\" y=\"78\">lit side day</text><text x=\"358\" y=\"42\">Dark side</text><text x=\"358\" y=\"78\">night</text></g></svg>"},{"alt":"Ball-and-torch demo.","caption":"Opposite side is night.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Torch</text><text x=\"28\" y=\"78\">Sun stand-in</text><text x=\"358\" y=\"42\">Ball</text><text x=\"358\" y=\"78\">Earth stand-in</text></g></svg>"}],"year_level":"Year 3"}') WHERE seed_key='s2-sci-y3-w21-l1' AND family_id IS NULL;
